<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { api } from '../api';
import { dateText, errorText, kindText, moduleNames, moduleText, post, statusText } from '../saas';
import '../saas.css';
const loading=ref(false);const saving=ref(false);const error=ref('');const current=ref<any>(null);const result=ref<any>(null);const form=reactive({kind:'EXTEND',modules:[] as string[],materialNote:'',adminName:'',adminUsername:''});
const history=computed(()=>current.value?.requests??current.value?.applications??current.value?.history??[]);
async function load(){loading.value=true;error.value='';try{current.value=await api('/saas/current');form.modules=[...(current.value.workspace?.modules??current.value.modules??[])]}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function submit(){error.value='';if(!form.materialNote.trim()){error.value='请填写申请依据和材料摘要';return}if(form.kind==='EXTEND'&&!form.modules.length){error.value='请至少选择一个申请模块';return}if(form.kind==='ADMIN_CHANGE'&&(!form.adminName.trim()||!form.adminUsername.trim())){error.value='请填写新管理员姓名和账号';return}saving.value=true;try{result.value=await post('/saas/change-requests',{kind:form.kind,modules:form.kind==='EXTEND'?form.modules:undefined,materialNote:form.materialNote,adminName:form.kind==='ADMIN_CHANGE'?form.adminName:undefined,adminUsername:form.kind==='ADMIN_CHANGE'?form.adminUsername:undefined});form.materialNote='';ElMessage.success('变更申请已提交，等待省级审核');await load()}catch(e){error.value=errorText(e)}finally{saving.value=false}}
onMounted(load);
</script>
<template><div class="saas-page" v-loading="loading"><h1 class="sr-only">授权变更申请</h1><div v-if="error" class="saas-error" role="alert"><span>{{error}}</span><el-button @click="load">重试</el-button></div><el-alert v-if="result" :title="`申请已提交：${result.businessNo??result.application?.businessNo??''}`" type="success" :closable="false"/><template v-if="current?.workspace"><div class="saas-panel"><h2>{{current.workspace.cityName}} · 当前授权</h2><el-descriptions :column="2" border><el-descriptions-item label="当前状态">{{statusText(current.workspace.status)}}</el-descriptions-item><el-descriptions-item label="授权有效期">{{current.workspace.validUntil?dateText(current.workspace.validUntil):'长期有效'}}</el-descriptions-item><el-descriptions-item label="已开通模块" :span="2">{{moduleText(current.workspace.modules??current.modules)}}</el-descriptions-item></el-descriptions></div><section class="saas-panel"><h2>提交变更申请</h2><el-form label-position="top" @submit.prevent="submit"><el-form-item label="申请事项" required><el-radio-group v-model="form.kind"><el-radio value="EXTEND">功能扩展</el-radio><el-radio value="RENEW">授权续期</el-radio><el-radio value="ADMIN_CHANGE">管理员变更</el-radio></el-radio-group></el-form-item><el-form-item v-if="form.kind==='EXTEND'" label="申请后的业务模块" required><el-checkbox-group v-model="form.modules"><el-checkbox v-for="(name,code) in moduleNames" :key="code" :value="code">{{name}}</el-checkbox></el-checkbox-group></el-form-item><div v-if="form.kind==='ADMIN_CHANGE'" class="saas-grid"><el-form-item label="新管理员姓名" required><el-input v-model="form.adminName" maxlength="50"/></el-form-item><el-form-item label="新管理员账号" required><el-input v-model="form.adminUsername" maxlength="40"/></el-form-item></div><el-form-item label="申请依据及材料摘要" required><el-input v-model="form.materialNote" type="textarea" :rows="4" maxlength="4000" show-word-limit aria-label="申请依据及材料摘要" placeholder="填写授权函编号、拟变更内容及办理依据。续期申请请注明期望的有效期限。"/></el-form-item><el-button native-type="submit" type="primary" :loading="saving">提交变更申请</el-button></el-form></section><section class="saas-panel"><h2>申请记录</h2><el-table :data="history" empty-text="暂无授权变更申请"><el-table-column prop="businessNo" label="申请编号" min-width="200"/><el-table-column label="事项" width="120"><template #default="{row}">{{kindText(row.kind)}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag type="info">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column prop="reviewComment" label="审核意见" min-width="220"/><el-table-column label="提交时间" min-width="170"><template #default="{row}">{{dateText(row.createdAt)}}</template></el-table-column></el-table></section></template><el-empty v-else-if="!loading&&!error" description="当前账号尚未关联城市工作空间"/></div></template>
